#!/usr/bin/env bash
# OPD v2 TEACHER /score server (hidden-state extraction -> shared FS) — in-container, Blackwell/B200.
# De-apptainer'd port of ycchen training/opd_v2/run_teacher_fs.sh:
#   * no `apptainer exec $SIF`; runs the image's serve venv
#   * the 4 teacher patches (deepseek_v4 / scheduler / output_processor / http_server out_path FS-write)
#     are BAKED into the venv at build time (generated by teacher_extract/_patch_sglang.py)
#   * TEACHER IS MLA (no attention sink) -> the triton-sink rule does NOT apply here.
#
# B200 TODO (flagged, not silently defaulted):
#   * `--moe-runner-backend marlin` is Ampere/Hopper int4; on Blackwell pick a supported MoE backend
#     (cutlass/triton/flashinfer) — benchmark. Override via MOE_BACKEND.
#   * MLA attention backend: set a Blackwell-capable one (flashinfer/triton) via ATTN_BACKEND if the
#     default isn't valid on sm_100.
#   * For an Olmo3 test-teacher instead of DeepSeek-V4-Flash, the hidden-extract patch differs
#     (olmo2_sink extraction, not deepseek_v4) — see OPD_V2_TRAIN_DOCKER_PLAN.md.
#
#   CUDA_VISIBLE_DEVICES=3 ./run_teacher.sh --tp 1 --port 8100
set -euo pipefail

# --- serve venv is CUDA-13 (sglang 0.5.14): use the CUDA-13 nvcc/CCCL for its runtime JIT kernels -----
# The base image defaults CUDA_HOME to cu128, but sglang JIT-compiles kernels (DeepSeek-V4 topk etc.)
# that use CUDA-13 cuda::ptx intrinsics -> point it at the CUDA-13 toolkit baked in the image (the
# base/trainer venv stays cu128).
export CUDA_HOME=/usr/local/cuda-13.0 CUDA_PATH=/usr/local/cuda-13.0
export PATH=/usr/local/cuda-13.0/bin:${PATH}

# --- CUDA-13 forward-compat (see Dockerfile cuda13compat stage) --------------------------------------
# sglang 0.5.14 is a CUDA-13 build and can't be pinned to cu128 (sgl-project/sglang#25069). If this
# node's driver predates CUDA 13, load the baked forward-compat libcuda so the serve stack runs on
# CUDA-12.x datacenter drivers (>=525). On a CUDA-13 driver this is skipped (native libcuda is used).
if [ -d /opt/cuda13-compat ]; then
  _cc=$(nvidia-smi 2>/dev/null | sed -n 's/.*CUDA Version: *\([0-9]\{1,\}\).*/\1/p' | head -1)
  if [ -n "${_cc}" ] && [ "${_cc}" -lt 13 ] 2>/dev/null; then
    export LD_LIBRARY_PATH="/opt/cuda13-compat:${LD_LIBRARY_PATH:-}"
    echo "[cuda13-compat] node driver CUDA ${_cc}.x < 13 -> forward-compat libcuda enabled" >&2
  fi
fi

# --- persistent JIT compile cache (opt-in) -----------------------------------------------------------
# DeepGEMM/flashinfer/sglang/tvm-ffi JIT-compile kernels PER GEMM shape (M = prefill length); the
# teacher's cold DeepGEMM warm is ~8 min/shape. Set JIT_CACHE_DIR to a durable shared-FS path (e.g. a
# Beaker Weka mount) and the compile caches persist across runs + instances -> warm start, no recompile.
# Unset -> default ~/.cache (behaviour unchanged). Arch-scoped (sm_90a H200 vs sm_100 B200 never collide)
# + role-scoped (replicas of a role share one cache). Redirect via symlink so it works regardless of each
# lib's env-var support; DG_JIT_CACHE_DIR is also set explicitly for DeepGEMM.
if [ -n "${JIT_CACHE_DIR:-}" ]; then
  _ccap=$(nvidia-smi --query-gpu=compute_cap --format=csv,noheader 2>/dev/null | head -1 | tr -d '. ') || true
  _jc="${JIT_CACHE_DIR%/}/sm${_ccap:-x}/teacher"; mkdir -p "$HOME/.cache"
  for _d in deep_gemm flashinfer sglang tvm-ffi triton; do
    mkdir -p "$_jc/$_d"
    if [ -e "$HOME/.cache/$_d" ] && [ ! -L "$HOME/.cache/$_d" ]; then
      cp -an "$HOME/.cache/$_d/." "$_jc/$_d/" 2>/dev/null || true; rm -rf "$HOME/.cache/$_d"
    fi
    ln -sfn "$_jc/$_d" "$HOME/.cache/$_d"
  done
  mkdir -p "$_jc/inductor"
  # Seed from the image's baked warm cache (sm_100, TP4): the compile cubins (deep_gemm/triton/flashinfer/
  # tvm-ffi) AND the flashinfer fp4 MoE autotune (sglang/flashinfer/autotune/…). cp -rn = never clobber a
  # warmer/newer entry, so a persistent (Weka) cache is untouched; a FRESH one skips both the ~10-20min cold
  # DeepGEMM/JIT compile AND the ~15min fp4 autotune -> teacher reaches /health in ~1-2min instead of ~16min.
  # Two switches, BOTH ON by default:
  #   JIT_CACHE_SEED=0    -> seed nothing (image never touches your JIT_CACHE_DIR)
  #   JIT_AUTOTUNE_SEED=0 -> seed the compile cache but DROP the baked autotune (re-tune per hardware). The
  #                          autotune is env-specific (keyed by flashinfer ver + sm100 + shape-hash); same arch
  #                          + same TP4 -> it transfers, but set 0 to force a fresh tune if you suspect drift.
  _seed="${OPD_JIT_CACHE_SEED:-/opt/opd/jit-cache-seed}/sm${_ccap:-x}/teacher"
  if [ "${JIT_CACHE_SEED:-1}" = "1" ] && [ -d "$_seed" ]; then
    _pre_at=$(find "$_jc" -type d -path '*flashinfer/autotune' 2>/dev/null | head -1)   # the user's own autotune, if any
    cp -rn "$_seed/." "$_jc/" 2>/dev/null || true                                        # compile (+ bundled autotune); cp -n never clobbers
    if [ "${JIT_AUTOTUNE_SEED:-1}" != "1" ] && [ -z "$_pre_at" ]; then
      rm -rf "$_jc"/*/flashinfer/autotune 2>/dev/null || true                            # drop ONLY the seed's autotune (never a pre-existing one)
    fi
    echo "[jit-cache] seeded compile$([ "${JIT_AUTOTUNE_SEED:-1}" = "1" ] && echo '+autotune') cache from baked seed ($_seed)" >&2
  fi
  export DG_JIT_CACHE_DIR="$HOME/.cache/deep_gemm" TRITON_CACHE_DIR="$HOME/.cache/triton" \
         TVM_FFI_CACHE_DIR="$HOME/.cache/tvm-ffi" TORCHINDUCTOR_CACHE_DIR="$_jc/inductor"
  echo "[jit-cache] persistent compile cache (sm${_ccap:-x}/teacher) -> $_jc" >&2
fi
SERVE_PY="${SERVE_PY:-/opt/venv/serve/bin/python}"
OPD_REPO="${OPD_REPO:-/opt/opd/repo}"
MODEL="${MODEL:-${DEEPSEEK_V4_FLASH:-/models/DeepSeek-V4-Flash}}"
TP="${TP:-4}"; PORT=8100
while [ $# -gt 0 ]; do case "$1" in --tp) TP="$2"; shift 2;; --port) PORT="$2"; shift 2;; *) shift;; esac; done

SPOOL="${SPOOL:-/dev/shm/opd-v2-teacher-spool}"; mkdir -p "$SPOOL"
# MoE backend: sglang `auto` MIS-picks on sm_100 for DeepSeek-V4 (experts are fp4 -> auto's fp8 triton
# runner CRASHES "Hidden size mismatch"; deep_gemm/flashinfer_trtllm fp8 paths also fail — fp8 MoE for V4
# is unsupported by design, sglang #25704/#23743). So AUTO-DETECT the arch and pick the right fp4 backend:
#   sm_100 (Blackwell B200/GB200) -> flashinfer_mxfp4  (fp4-native; validated 2026-07-13, clean proof + 40-45k
#                                     tok/s prefill; SAME precision as her Hopper marlin fp4 experts)
#   else (Hopper etc.)            -> auto               (-> marlin = her V33)
# This IMPLEMENTS her per-hardware intent that sglang's own `auto` gets wrong on sm_100. Override MOE_BACKEND
# to force any backend. One-time ~15min flashinfer fp4 autotune on first launch (add --disable-flashinfer-autotune
# below for a fast cold start; the JIT compile persists via JIT_CACHE_DIR).
if [ -z "${MOE_BACKEND:-}" ]; then
  _ccmaj=$(nvidia-smi --query-gpu=compute_cap --format=csv,noheader 2>/dev/null | head -1 | cut -d. -f1)
  if [ "${_ccmaj:-0}" = "10" ]; then MOE_BACKEND=flashinfer_mxfp4; else MOE_BACKEND=auto; fi
fi
ATTN_ARGS=(); [ -n "${ATTN_BACKEND:-}" ] && ATTN_ARGS+=(--attention-backend "$ATTN_BACKEND")
# B200: sglang #23743's FlashMLA mixed decode+multi-prefill crash — set MAX_PREFILL_TOKENS=8192 to avoid it.
PREFILL_ARGS=(); [ -n "${MAX_PREFILL_TOKENS:-}" ] && PREFILL_ARGS+=(--max-prefill-tokens "$MAX_PREFILL_TOKENS")
DIST_ARGS=()
[ -n "${DIST_INIT_ADDR:-}" ]  && DIST_ARGS+=(--dist-init-addr "$DIST_INIT_ADDR")
[ -n "${SGLANG_NCCL_PORT:-}" ] && DIST_ARGS+=(--nccl-port "$SGLANG_NCCL_PORT")

export SGLANG_DSV4_HIDDEN_POST_NORM=1 \
       SGLANG_JIT_DEEPGEMM_FAST_WARMUP=1 \
       SGLANG_OPT_FP8_WO_A_GEMM=0 \
       MALLOC_ARENA_MAX=4 \
       SGLANG_HIDDEN_SPOOL_DIR="$SPOOL" \
       SGLANG_HIDDEN_CODEC_DIR="$OPD_REPO/training/_common" \
       OPD_V2_SRC="$OPD_REPO/training/opd_v2/src" \
       OPD_TEACHER_MODEL_PATH="$MODEL" \
       OPD_SCORE_TOP1_CHUNK="${OPD_SCORE_TOP1_CHUNK:-1024}"

exec "$SERVE_PY" -m sglang.launch_server --skip-server-warmup \
  --model-path "$MODEL" --tp-size "$TP" --host 0.0.0.0 --port "$PORT" \
  "${DIST_ARGS[@]}" "${ATTN_ARGS[@]}" "${PREFILL_ARGS[@]}" \
  --enable-return-hidden-states --disable-radix-cache \
  --chunked-prefill-size "${CHUNKED_PREFILL:-11264}" --mem-fraction-static "${MEMFRAC:-0.80}" \
  --max-running-requests "${MAXRUN:-128}" --disable-cuda-graph \
  --context-length "${TEACHER_CONTEXT_LEN:-${CONTEXT_LEN:-69632}}" \
  --moe-runner-backend "$MOE_BACKEND" \
  --watchdog-timeout 1800 --log-level info
